function maxSumSubmatrix(matrix, k) {
  const rows = matrix.length, cols = matrix[0].length;
  let maxSum = -Infinity;
  for (let i = 0; i <= rows - k; i++) {
    for (let j = 0; j <= cols - k; j++) {
      let sum = 0;
      for (let r = i; r < i + k; r++) {
        for (let c = j; c < j + k; c++) sum += matrix[r][c];
      }
      maxSum = Math.max(maxSum, sum);
    }
  }
  return maxSum;
}
